import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Basic-Widgets","description":"","frontmatter":{"title":"Basic-Widgets"},"headers":[],"relativePath":"projects/grafik-visual-studio/basic.md","filePath":"projects/grafik-visual-studio/basic.md","lastUpdated":1793128957000}'),a={name:"projects/grafik-visual-studio/basic.md"};function s(u,e,l,d,o,g){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="basic-widgets" tabindex="-1">Basic-Widgets <a class="header-anchor" href="#basic-widgets" aria-label="Permalink to &quot;Basic-Widgets&quot;">​</a></h1><p>Ab <strong>Studio 0.1.293</strong> erhalten die 48 Basic-Einträge die Ergänzungen aus dem VIS-2-Abgleich. Die Widgets sind eigenständige HA-Umsetzungen. Bestehende Projekte behalten IDs, gespeicherte Gruppen-Schlüssel, Werte, CSS und bisherige Modi. Neue Darstellungen werden für alte Widgets erst nach ausdrücklicher Auswahl verwendet.</p><p><strong>Basic-Sprache</strong> wählt automatisch aus Studio oder separat DE/EN/FR. Das betrifft Eigenschaften, Hinweise und neue Basic-Runtime-Meldungen. Eigene Texte und Entitätswerte bleiben erhalten; die gesamte Studio-Oberfläche bleibt DE/EN.</p><h2 id="werte-und-aktionen" tabindex="-1">Werte und Aktionen <a class="header-anchor" href="#werte-und-aktionen" aria-label="Permalink to &quot;Werte und Aktionen&quot;">​</a></h2><p>Number bietet Tausendertrennung, automatische Nachkommastellen, Qualitätsentität und CSS-Klassen. „VIS-2-kompatibel“ aktiviert ausdrücklich numerisches Präfix-Parsing und Singularwahl nach Formatierung; der bisherige Modus bleibt erhalten. Bool HTML/control ergänzt Min-/Max-Sentinels, HTML-Zusätze und zusätzliche HA-Schreibziele für true/false. Der Server prüft unterstützte Entitäten, Verfügbarkeit und Grenzen. Haupt- und Zusatzaktion sind keine atomare Transaktion; nach Fehlern beim Zusatzschreiben folgt keine Zusatz-URL.</p><p><strong>AckFlag HTML</strong> erhält eine ausdrückliche Bestätigungsentität oder ein Attribut. HA besitzt kein ioBroker-ACK-Flag. Alte Projekte behalten die bisherige Zustandsquelle; fehlende Bestätigung wird nicht als bestätigt ausgegeben.</p><p>Links bieten Zielfenster. Notizen können bereinigtes HTML anzeigen; der Dialog schreibt weiterhin nur Text an verfügbare input_text-Helfer ohne Attribut. Neue Widgets verwenden inerte HTML-Formatierung. Der bisherige Modus und der gespeicherte HTML-Code alter Projekte bleiben erhalten. Komplexe Webseiten gehören in iFrame; ausführbare ioBroker-Bindings werden nicht übernommen.</p><h2 id="darstellung-und-navigation" tabindex="-1">Darstellung und Navigation <a class="header-anchor" href="#darstellung-und-navigation" aria-label="Permalink to &quot;Darstellung und Navigation&quot;">​</a></h2><p>Unter <strong>Extrasteuerung → Steuerungsziel</strong> lässt sich „Hauptziel und Zusatzaktion“ oder „Nur separates Ziel“ wählen. Der zweite Modus schreibt ausschließlich an das separate Ziel; eine Richtung ohne konfiguriertes Ziel bleibt deaktiviert und fällt nicht auf das Hauptziel zurück.</p><p>Checkbox, Select und Bar bieten bisherige, native und moderne Darstellung. Tabellen erhalten klassische tclass-Hooks und eine moderne Darstellung mit festem Header. JSON, Ereignisse, Auswahl, Bestätigung, Details und Spalten bleiben nutzbar. Eigene VIS-CSS-Regeln können Anpassungen erfordern; der DOM ist nicht pixelgenau identisch.</p><p>Neue Vollbild-Widgets verwenden wechselnde Icons, erkennen Escape und sind im Editor deaktiviert. Alte Textbuttons bleiben erhalten. HTML navigation kann gezielt die Seite eines View-in-widget-Containers wechseln, ohne die Hauptseite zu verlassen. Screen Resolution kann Projekt-/Seitendetails zeigen. Gruppierung verwendet die bestehenden Studio-Gruppen.</p><p>Lokalisierte Zeiten unterstützen auto, Datums-/Zeitteile, Monats-/Wochentagsnamen, 12-Stunden-Uhr, Millisekunden und <code>[Literale]</code>. Für numerische Zeitstempel Sekunden oder Millisekunden ausdrücklich wählen; auto nutzt eine Größenheuristik. Relative Zeit aktualisiert sich jede Sekunde. TimesValue und Timestamp Value bleiben absichtlich zwei Einträge mit gleicher Quellart.</p><h2 id="spracheingabe-runtime-verlassen-und-gruppen" tabindex="-1">Spracheingabe, Runtime verlassen und Gruppen <a class="header-anchor" href="#spracheingabe-runtime-verlassen-und-gruppen" aria-label="Permalink to &quot;Spracheingabe, Runtime verlassen und Gruppen&quot;">​</a></h2><p>Speech to Text startet nur nach Klick. Es bietet einmal/Start-Stopp/fortlaufend, DE/EN/FR-Erkennungssprache, Schlüsselwortfilter, fünf Statusbilder und Farben. Ausgabe lokal oder an verfügbaren input_text. Browserunterstützung, Mikrofonfreigabe und meist HTTPS sind erforderlich; der Erkennungsdienst des Browsers kann Internet benötigen.</p><p>HTML logout verlässt die Runtime zur Rückkehr-URL oder versucht ein per Skript geöffnetes Fenster zu schließen. <strong>Es meldet das HA-Konto nicht ab.</strong></p><p>Gruppen-Sichtbarkeit verwendet HA-Gruppen-IDs wie <code>system-admin</code> und <code>system-users</code>, getrennt durch Semikolon. Nur aktive, vom Ingress-Proxy bestätigte Benutzer erhalten Gruppen; lokale/unbekannte Benutzer erhalten keine. Bei nicht passender Gruppe oder Zustandsbedingung gilt Ausblenden/Deaktivieren. Dies ist Darstellungslogik, keine zusätzliche API-Zugriffskontrolle.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/basic-widgets-0.1.293.md" target="_blank" rel="noreferrer">Ausführliche Anleitung DE/EN/FR</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/vis2-basic-audit-2026-10-12.md" target="_blank" rel="noreferrer">VIS-2-Prüfbericht zum vorherigen Stand</a> · <a href="/en/projects/grafik-visual-studio/basic">English</a> · <a href="/fr/projects/grafik-visual-studio/basic">Français</a>.</p>',17)])])}const b=t(a,[["render",s]]);export{c as __pageData,b as default};
